import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import vm from 'node:vm';
import { webcrypto } from 'node:crypto';

// A small DOM stand-in for event/storage integration. This is not browser rendering.
const html = readFileSync(new URL('../index.html', import.meta.url), 'utf8');
const modelSource = readFileSync(new URL('../model.js', import.meta.url), 'utf8');
const appSource = readFileSync(new URL('../app.js', import.meta.url), 'utf8');

function boot(initialRaw = null) {
  const ids = [...html.matchAll(/id="([^"]+)"/g)].map(match => match[1]);
  const elements = new Map();
  let focused = null;
  let confirmation = true;
  const windowListeners = new Map();
  class Element {
    constructor(id = '') { this.id = id; this.value = ''; this.textContent = ''; this.hidden = false; this.dataset = {}; this.children = []; this.listeners = new Map(); this.attributes = {}; }
    addEventListener(name, callback) { this.listeners.set(name, callback); }
    fire(name, extra = {}) { return this.listeners.get(name)?.({ preventDefault() {}, target: this, ...extra }); }
    append(...children) { this.children.push(...children); }
    replaceChildren() { this.children = []; }
    setAttribute(name, value) { this.attributes[name] = value; }
    focus() { focused = this; }
    scrollIntoView() {}
    showModal() { this.open = true; }
    reset() { elements.get('note-body').value = ''; elements.get('note-category').value = 'other'; }
  }
  for (const id of ids) elements.set(id, new Element(id));
  elements.get('filter').value = 'all';
  elements.get('note-category').value = 'other';
  let raw = initialRaw;
  let failWrites = false;
  const storage = { getItem() { return raw; }, setItem(key, value) { if (failWrites) throw new Error('QuotaExceededError'); raw = value; } };
  const context = vm.createContext({ document: { getElementById(id) { assert.ok(elements.has(id), `Missing element: ${id}`); return elements.get(id); }, createElement() { return new Element(); } }, window: { localStorage: storage, addEventListener(name, callback) { windowListeners.set(name, callback); } }, crypto: webcrypto, confirm: () => confirmation, Intl, Date, Blob, URL, setTimeout });
  vm.runInContext(modelSource, context);
  vm.runInContext(appSource, context);
  return { get: id => elements.get(id), get raw() { return raw; }, get focused() { return focused; }, set failWrites(value) { failWrites = value; }, set confirmation(value) { confirmation = value; }, fireWindow(name, event) { windowListeners.get(name)?.(event); } };
}

function save(app, body, category = 'other') {
  app.get('note-body').value = body;
  app.get('note-category').value = category;
  app.get('note-form').fire('submit');
}

test('입력 → 저장 → 앱 재시작 → 검색 → 수정 → 삭제 → 되돌리기 이벤트 연결', () => {
  let app = boot();
  save(app, '가상 선반 스케치', 'idea');
  assert.equal(app.get('note-body').value, '');
  assert.equal(app.get('note-list').children.length, 1);
  app = boot(app.raw);
  assert.equal(app.get('note-list').children[0].children[1].textContent, '가상 선반 스케치');
  app.get('search').value = '없음';
  app.get('search').fire('input');
  assert.equal(app.get('note-list').children.length, 0);
  app.get('clear-filters').fire('click');
  let card = app.get('note-list').children[0];
  card.children[2].children[0].fire('click');
  save(app, '가상 수정한 스케치', 'observation');
  card = app.get('note-list').children[0];
  assert.equal(card.children[1].textContent, '가상 수정한 스케치');
  card.children[2].children[1].fire('click');
  assert.equal(app.get('delete-dialog').open, true);
  app.get('delete-dialog').returnValue = 'delete';
  app.get('delete-dialog').fire('close');
  assert.equal(JSON.parse(app.raw).notes.length, 0);
  assert.equal(app.focused.id, 'undo-delete');
  app.get('undo-delete').fire('click');
  assert.equal(JSON.parse(app.raw).notes[0].body, '가상 수정한 스케치');
});

test('저장 실패는 입력, 목록과 기존 저장 원문을 보존한다', () => {
  const app = boot();
  save(app, '가상 기존 기록');
  const raw = app.raw;
  app.failWrites = true;
  save(app, '가상 아직 저장되지 않은 입력');
  assert.equal(app.raw, raw);
  assert.equal(app.get('note-body').value, '가상 아직 저장되지 않은 입력');
  assert.equal(app.get('note-list').children.length, 1);
  assert.match(app.get('storage-error').textContent, /저장하지 못했어요/);
});

test('손상 원문은 보존하고 저장·가져오기·내보내기를 잠근다', () => {
  const app = boot('{broken');
  assert.equal(app.raw, '{broken');
  for (const id of ['save-button', 'import', 'export']) assert.equal(app.get(id).disabled, true);
  assert.equal(app.get('result-count').textContent, '불러오기 실패');
});

test('삭제 취소는 기록과 원문을 바꾸지 않는다', () => {
  const app = boot();
  save(app, '가상 취소 테스트');
  const raw = app.raw;
  app.get('note-list').children[0].children[2].children[1].fire('click');
  app.get('delete-dialog').returnValue = 'cancel';
  app.get('delete-dialog').fire('close');
  assert.equal(app.raw, raw);
  assert.equal(app.get('note-list').children.length, 1);
});

test('새 메모와 수정의 빈 입력을 거부하고 원본을 보존한 채 다시 저장할 수 있다', () => {
  const app = boot();
  save(app, '가상 저장 원본', 'idea');
  const raw = app.raw;
  for (const body of ['', ' \n\t']) {
    save(app, body);
    assert.equal(app.raw, raw);
    assert.equal(app.get('note-body').value, body);
    assert.match(app.get('storage-error').textContent, /내용을 입력/);
  }
  app.get('note-body').value = '';
  app.get('note-list').children[0].children[2].children[0].fire('click');
  save(app, ' \n');
  assert.equal(app.raw, raw);
  assert.equal(app.get('save-button').textContent, '수정 저장');
  save(app, '가상 다시 쓴 내용', 'observation');
  const records = JSON.parse(app.raw).notes;
  assert.equal(records.length, 1);
  assert.equal(records[0].id, JSON.parse(raw).notes[0].id);
  assert.equal(records[0].body, '가상 다시 쓴 내용');
});

test('수정 취소는 원본을 보존하고 이후 새 입력은 별도 기록으로 저장한다', () => {
  const app = boot();
  save(app, '가상 원본', 'idea');
  const raw = app.raw;
  app.get('note-list').children[0].children[2].children[0].fire('click');
  app.get('note-body').value = '가상 취소할 수정';
  app.get('note-category').value = 'todo';
  app.get('cancel-edit').fire('click');
  assert.equal(app.raw, raw);
  assert.equal(app.get('note-body').value, '');
  assert.equal(app.get('save-button').textContent, '메모 남기기');
  save(app, '가상 새 기록', 'other');
  const records = JSON.parse(app.raw).notes;
  assert.equal(records.length, 2);
  assert.deepEqual(records[0], JSON.parse(raw).notes[0]);
  assert.notEqual(records[0].id, records[1].id);
});

test('취소 확인을 거절하면 편집 내용과 대상이 유지되어 같은 기록을 수정한다', () => {
  const app = boot();
  save(app, '가상 원본');
  const original = JSON.parse(app.raw).notes[0];
  app.get('note-list').children[0].children[2].children[0].fire('click');
  app.get('note-body').value = '가상 유지할 수정';
  app.confirmation = false;
  app.get('cancel-edit').fire('click');
  assert.equal(app.get('note-body').value, '가상 유지할 수정');
  save(app, app.get('note-body').value, 'todo');
  const records = JSON.parse(app.raw).notes;
  assert.equal(records.length, 1);
  assert.equal(records[0].id, original.id);
  assert.equal(records[0].body, '가상 유지할 수정');
});

test('수정 중 앱 재시작은 저장 전 원본을 되살리고 편집 대상을 초기화한다', () => {
  let app = boot();
  save(app, '가상 원본', 'idea');
  const raw = app.raw;
  app.get('note-list').children[0].children[2].children[0].fire('click');
  app.get('note-body').value = '가상 저장하지 않은 변경';
  app.get('note-category').value = 'todo';
  assert.equal(app.raw, raw);
  app = boot(app.raw);
  assert.equal(app.get('note-list').children[0].children[1].textContent, '가상 원본');
  assert.equal(app.get('note-body').value, '');
  save(app, '가상 새로 쓴 기록');
  assert.deepEqual(JSON.parse(app.raw).notes[0], JSON.parse(raw).notes[0]);
  assert.equal(JSON.parse(app.raw).notes.length, 2);
});

test('내용을 모두 지운 편집도 저장되지 않은 변경으로 떠나기 경고를 요청한다', () => {
  const app = boot();
  save(app, '가상 원본');
  app.get('note-list').children[0].children[2].children[0].fire('click');
  app.get('note-body').value = '';
  let prevented = false;
  app.fireWindow('beforeunload', { preventDefault() { prevented = true; } });
  assert.equal(prevented, true);
  assert.equal(JSON.parse(app.raw).notes[0].body, '가상 원본');
});

test('변경 없는 편집에는 떠나기 경고가 없고 분류만 수정하면 경고를 요청한다', () => {
  const app = boot();
  save(app, '가상 원본', 'idea');
  app.get('note-list').children[0].children[2].children[0].fire('click');
  let prevented = false;
  app.fireWindow('beforeunload', { preventDefault() { prevented = true; } });
  assert.equal(prevented, false);
  app.get('note-category').value = 'todo';
  app.fireWindow('beforeunload', { preventDefault() { prevented = true; } });
  assert.equal(prevented, true);
  assert.equal(JSON.parse(app.raw).notes[0].category, 'idea');
});

test('저장 실패 후 수정 취소와 새 작성이 원본을 덮어쓰지 않는다', () => {
  const app = boot();
  save(app, '가상 원본');
  const original = JSON.parse(app.raw).notes[0];
  app.get('note-list').children[0].children[2].children[0].fire('click');
  app.failWrites = true;
  save(app, '가상 실패한 수정');
  app.get('cancel-edit').fire('click');
  app.failWrites = false;
  save(app, '가상 새 작성');
  const records = JSON.parse(app.raw).notes;
  assert.equal(records.length, 2);
  assert.deepEqual(records[0], original);
  assert.equal(records[1].body, '가상 새 작성');
});

test('잘못된 필드가 섞인 저장 데이터는 한 건도 덮어쓰지 않고 잠근다', () => {
  const fixture = boot();
  save(fixture, '가상 정상 기록', 'idea');
  const valid = JSON.parse(fixture.raw).notes[0];
  const badValues = [null, [], { ...valid, id: 'bad-category', category: ['idea'] }, { ...valid, id: 'bad-body', body: ' \n' }, { ...valid, id: 'bad-date', updatedAt: 'yesterday' }];
  for (const bad of badValues) {
    const raw = JSON.stringify({ version: 1, notes: [valid, bad] });
    const app = boot(raw);
    assert.equal(app.get('save-button').disabled, true);
    assert.equal(app.get('result-count').textContent, '불러오기 실패');
    save(app, '가상 덮어쓰기 시도');
    assert.equal(app.raw, raw);
  }
});
